'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const d2n=s=>{const[a,b,c]=s.split('-').map(Number);return Math.round(Date.UTC(a,b-1,c)/864e5)};
const n2d=n=>new Date(n*864e5).toISOString().slice(0,10);
const p2=n=>String(n).padStart(2,'0');
const today=()=>{const d=new Date();return d.getFullYear()+'-'+p2(d.getMonth()+1)+'-'+p2(d.getDate())};
const MES=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const formatDate=(s,sh)=>{const[y,m,d]=s.split('-').map(Number);return d+' de '+MES[m-1]+(sh?'':' de '+y)};
const dm=s=>p2(+s.slice(8))+'/'+s.slice(5,7);
const validDate=s=>/^\d{4}-\d\d-\d\d$/.test(s||'')&&n2d(d2n(s))===s;
const plural=(n,a,b)=>n+' '+(Math.abs(n)===1?a:b);
const Q=[['normal','♥','Normal'],['bem','😊','Bem'],['cansada','😴','Cansada'],['colicas','😣','Cólicas'],['triste','😔','Triste'],['cabeca','🤕','Dor de cabeça'],['irritada','😡','Irritada'],['inchaco','💧','Inchaço']];
const MOOD=['Feliz','Normal','Triste','Irritada','Ansiosa','Sensível'],SYM=['Cólicas','Dor de cabeça','Dor lombar','Acne','Inchaço','Cansaço','Sensibilidade mamária','Náuseas'],FLOW=['Ligeiro','Moderado','Intenso'];
const MSG=['Hoje é um bom dia para cuidar de ti. ♥','Não te esqueças de descansar.','Escuta o teu corpo.','Cuida de ti com carinho.','Bebe água e respira fundo.','Um passo de cada vez.'];
/* ===== base de dados (IndexedDB) ===== */
let db;
const openDB=()=>new Promise((res,rej)=>{const r=indexedDB.open('fanny-app',1);r.onupgradeneeded=()=>{const d=r.result;d.createObjectStore('profile',{keyPath:'id'});d.createObjectStore('cycles',{keyPath:'id',autoIncrement:true});d.createObjectStore('logs',{keyPath:'date'});d.createObjectStore('settings',{keyPath:'k'})};r.onsuccess=()=>{db=r.result;res()};r.onerror=()=>rej(r.error)});
const tx=(s,m,f)=>new Promise((res,rej)=>{const t=db.transaction(s,m),o=f(t.objectStore(s));t.oncomplete=()=>res(o&&o.result);t.onerror=()=>rej(t.error)});
const dbAll=s=>tx(s,'readonly',o=>o.getAll()),dbPut=(s,v)=>tx(s,'readwrite',o=>o.put(v)),dbDel=(s,k)=>tx(s,'readwrite',o=>o.delete(k)),dbClr=s=>tx(s,'readwrite',o=>o.clear());
let S={profile:null,cycles:[],logs:{},cfg:{}};
async function load(){const p=await dbAll('profile');S.profile=p[0]||null;S.cycles=(await dbAll('cycles')).sort((a,b)=>d2n(a.start)-d2n(b.start));S.logs={};(await dbAll('logs')).forEach(l=>S.logs[l.date]=l);const c=(await dbAll('settings')).find(x=>x.k==='cfg');S.cfg=c?c.v:{}}
const saveCfg=()=>dbPut('settings',{k:'cfg',v:S.cfg});
/* ===== cálculos ===== */
function calculateCycleLength(i){const c=S.cycles;return i<c.length-1?d2n(c[i+1].start)-d2n(c[i].start):null}
const cycleLens=()=>S.cycles.map((_,i)=>calculateCycleLength(i)).filter(x=>x!==null);
function calculateAverageCycle(){const l=cycleLens().filter(x=>x>=15&&x<=60).slice(-6);return l.length?Math.round(l.reduce((a,b)=>a+b)/l.length):S.profile.cycleLen}
function calculatePeriodDuration(c){return c.end?d2n(c.end)-d2n(c.start)+1:null}
function avgPeriod(){const l=S.cycles.map(calculatePeriodDuration).filter(Boolean);return l.length?Math.round(l.reduce((a,b)=>a+b)/l.length):S.profile.periodLen}
const lastC=()=>S.cycles[S.cycles.length-1];
const calculateNextPeriod=()=>n2d(d2n(lastC().start)+calculateAverageCycle());
const daysUntilPeriod=()=>d2n(calculateNextPeriod())-d2n(today());
function calculatePredictionConfidence(){const l=cycleLens();if(l.length<2)return'low';const m=l.reduce((a,b)=>a+b)/l.length;return Math.sqrt(l.reduce((a,b)=>a+(b-m)**2,0)/l.length)>5?'approx':'ok'}
function calculateCyclePhase(){const c=lastC();if(!c)return null;const day=d2n(today())-d2n(c.start),cl=calculateAverageCycle(),pl=avgPeriod(),ov=cl-14;let n=day<pl?'Menstruação':day<ov-1?'Fase folicular':day<=ov+1?'Ovulação (estimativa)':day<cl?'Fase lútea':'Ciclo mais longo que o previsto';return{day,cl,pl,ov,n}}
/* ===== segurança PIN / biometria ===== */
async function hash(s){const salt=S.cfg.salt||(S.cfg.salt=Math.random().toString(36).slice(2)+Date.now());if(window.crypto&&crypto.subtle){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(salt+s));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}let h=5381;for(const ch of salt+s)h=(h*33^ch.charCodeAt(0))>>>0;return'f'+h}
const b64=u=>btoa(String.fromCharCode(...new Uint8Array(u)));
async function bioReg(){try{const r=await navigator.credentials.create({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),rp:{name:'My Cycle+'},user:{id:crypto.getRandomValues(new Uint8Array(16)),name:'fanny',displayName:'Fanny'},pubKeyCredParams:[{type:'public-key',alg:-7},{type:'public-key',alg:-257}],authenticatorSelection:{authenticatorAttachment:'platform',userVerification:'required'},timeout:60000}});S.cfg.bio=b64(r.rawId);await saveCfg();return true}catch(e){return false}}
async function bioAuth(){try{await navigator.credentials.get({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),allowCredentials:[{type:'public-key',id:Uint8Array.from(atob(S.cfg.bio),c=>c.charCodeAt(0))}],userVerification:'required',timeout:60000}});return true}catch(e){return false}}
/* ===== UI base ===== */
let V='home',cm=(()=>{const d=new Date();return{y:d.getFullYear(),m:d.getMonth()}})();
const NAVOF={gkick:'home',gweight:'home',gbag:'home',prof:'home',notif:'home',hist:'more',phases:'more',learn:'more',help:'more',sett:'more'};
const toast=m=>{const t=$('#toast');t.textContent=m;t.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>t.hidden=true,2800)};
const sheet=h=>{$('#pn').innerHTML=h;$('#sh').hidden=false};
const closeSheet=()=>$('#sh').hidden=true;
function theme(){const t=localStorage.getItem('ff-theme')||'auto';document.documentElement.dataset.t=t;const m=document.querySelector('meta[name=theme-color]');if(m)m.content=t==='dark'?'#17111a':'#7a2b45'}
function render(){const m={gkick,gweight,gbag,prof,notif,home,cal,diary,stats,more,hist,phases,learn,help,sett};$('#main').innerHTML='<div class="pg">'+m[V]()+'</div>';$$('.nv button').forEach(b=>b.classList.toggle('on',b.dataset.v===(NAVOF[V]||V)));window.scrollTo(0,0)}
const back=()=>'<div class="top" style="margin-bottom:14px"><button data-a="go" data-v="more" aria-label="Voltar">‹</button></div>';
const chips=(g,arr,sel,single)=>'<div class="chips">'+arr.map(x=>`<button type="button" class="chip${(single?sel===x:(sel||[]).includes(x))?' on':''}" data-a="chip" data-g="${g}" data-s="${single?1:0}">${esc(x)}</button>`).join('')+'</div>';
/* ===== páginas ===== */
const fc=(bg,x)=>`<svg viewBox="0 0 40 40" aria-hidden="true"><circle cx="20" cy="20" r="18" fill="${bg}"/><g fill="none" stroke="#5a1f36" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">${x}</g></svg>`,dt=(x,y)=>`<circle cx="${x}" cy="${y}" r="1.9" fill="#5a1f36" stroke="none"/>`;
const FACE={normal:fc('#f3d9e2',dt(14,18)+dt(26,18)+'<path d="M14 26h12"/>'),
bem:fc('#fde3b0','<path d="M11.5 19q2.5-4 5 0M23.5 19q2.5-4 5 0"/><path d="M13 24q7 8 14 0"/>'),
cansada:fc('#d9d4f2','<path d="M11.5 18q2.5 3 5 0M23.5 18q2.5 3 5 0"/><circle cx="20" cy="27" r="2.2"/><path d="M29 6h5l-5 6h5" stroke-width="1.8"/>'),
colicas:fc('#f6c3c3','<path d="M11 15l5 3-5 3M29 15l-5 3 5 3"/><path d="M13 28q2-3 4 0t4 0t4 0"/>'),
triste:fc('#cfe0f3',dt(14,19)+dt(26,19)+'<path d="M10.5 15.5l5-2M29.5 15.5l-5-2"/><path d="M14 29q6-6 12 0"/><path d="M14 22q-2.5 3.5 0 4.5 2.5-1 0-4.5z" fill="#8bb8e8" stroke="none"/>'),
cabeca:fc('#f6d5bd','<path d="M11.5 18h5M23.5 18h5"/><path d="M14 28q6-4 12 0"/><path d="M8 8l3 3M20 4v4M32 8l-3 3" stroke="#c0394f" stroke-width="2"/>'),
irritada:fc('#f4b5ae',dt(14,19)+dt(26,19)+'<path d="M10.5 13l6 3M29.5 13l-6 3"/><path d="M14 28q6-5 12 0"/>'),
inchaco:fc('#cfeae4',dt(14,18)+dt(26,18)+'<path d="M16 25q4 3 8 0"/><circle cx="10" cy="24" r="3.6" fill="#f0a8a0" stroke="none" opacity=".7"/><circle cx="30" cy="24" r="3.6" fill="#f0a8a0" stroke="none" opacity=".7"/><path d="M30 5c3 3.5 4 5.5 4 7.5a4 4 0 01-8 0c0-2 1-4 4-7.500z" fill="#6fa8e8" stroke="none"/>')};
let REV=false,revT;
const hmQ=()=>{const tl=S.logs[today()]||{};return `<h2 class="hm-t">Como te sentes hoje?</h2><div class="chips q">${Q.map(x=>`<button class="chip${(tl.q||[]).includes(x[0])?' on':''}" data-a="quick" data-k="${x[0]}"><span>${FACE[x[0]]}</span>${x[2]}</button>`).join('')}</div><button class="btn s" data-a="day" data-d="${today()}">+ Registar hoje</button>`};
function home(){if(S.cfg.preg&&S.cfg.preg.on)return pregHome();const nx=calculateNextPeriod(),du=daysUntilPeriod(),cf=calculatePredictionConfidence(),ph=calculateCyclePhase(),dsc=S.cfg.discreet&&!REV;
const pct=Math.min(1,Math.max(0,ph.day/ph.cl)),C=2*Math.PI*44;
const big=du>0?'Daqui a '+plural(du,'dia','dias'):du===0?'Prevista para hoje':'Atraso de '+plural(-du,'dia','dias');
const conf=cf==='low'?'A aprender o teu ciclo':cf==='approx'?'Previsão aproximada':'';
return `${hdr()}
<div class="hm-hero"><div class="hm-hl"><span class="hm-k">Próxima menstruação</span><div class="hm-big ${dsc?'bl':''}" data-a="reveal">${big}</div><div class="hm-d ${dsc?'bl':''}" data-a="reveal">${ic('cal')}<span>${formatDate(nx,1)}</span></div>${conf?`<span class="hm-pill">${conf}</span>`:''}</div>
<svg class="ring" viewBox="0 0 104 104"><circle cx="52" cy="52" r="44" stroke="rgba(255,255,255,.25)"/><circle cx="52" cy="52" r="44" stroke="#fff" stroke-dasharray="${C}" stroke-dashoffset="${C*(1-pct)}" transform="rotate(-90 52 52)" style="transition:stroke-dashoffset 1.2s ease"/><text x="52" y="50" text-anchor="middle" fill="#fff" font-size="22" font-family="Georgia">${dsc?'•':ph.day+1}</text><text x="52" y="66" text-anchor="middle" fill="#fff" font-size="10" font-family="system-ui">dia do ciclo</text></svg></div>
<div class="hm-stats"><div class="hm-s"><span class="si t1">${ic('drop')}</span><div><b>${plural(avgPeriod(),'dia','dias')}</b><small>Período</small></div></div><div class="hm-s"><span class="si t2">${ic('cyc')}</span><div><b>${plural(calculateCycleLength.avg=calculateAverageCycle(),'dia','dias')}</b><small>Ciclo</small></div></div></div>
<div class="hm-card"><div class="hm-ph"><span class="hm-dot"></span><div><small>${dsc?'Fase do ciclo oculta':'Fase atual (estimativa)'}</small><b>${dsc?'•••':ph.n}</b></div></div><p class="hm-msg">${MSG[new Date().getDate()%MSG.length]}</p></div>
<button class="btn hm-cta" data-a="startP">${ic('drop')}<span>Minha menstruação começou</span></button>
${hmQ()}
${widgets()}`}
const LGI=(c,t)=>`<span><i style="${c}"></i>${t}</span>`;
function cal(){const pg=S.cfg.preg&&S.cfg.preg.on,AP=new Set(pg?apptDates().map(a=>a.d):[]),{y,m}=cm,first=new Date(Date.UTC(y,m,1)),off=(first.getUTCDay()+6)%7,nd=new Date(Date.UTC(y,m+1,0)).getUTCDate(),pl=avgPeriod(),P=new Set(),F=new Set(),V=new Set();
S.cycles.forEach(c=>{const s=d2n(c.start),e=c.end?d2n(c.end):s+pl-1;for(let i=s;i<=e;i++)P.add(i)});
if(lastC()&&!(S.cfg.preg&&S.cfg.preg.on)){const cl=calculateAverageCycle(),s0=d2n(lastC().start),t0=d2n(today());for(let i=0;i<pl;i++){const n=s0+cl+i;if(!P.has(n))F.add(n)}if(S.cfg.calFert)for(let k=1;k<=3;k++){const ov=s0+cl*k-14;if(ov>=t0){for(let i=-5;i<=0;i++){const n=ov+i;if(!P.has(n)&&!F.has(n))V.add(n)}break}}}
const has={};let cells=['S','T','Q','Q','S','S','D'].map(x=>`<div class="h">${x}</div>`).join('')+'<span></span>'.repeat(off);
for(let d=1;d<=nd;d++){const ds=y+'-'+p2(m+1)+'-'+p2(d),n=d2n(ds);has[P.has(n)?'p':F.has(n)?'f':V.has(n)?'v':'x']=1;if(S.logs[ds])has.l=1;if(ds===today())has.t=1;cells+=`<button data-a="day" data-d="${ds}" class="${P.has(n)?'p ':F.has(n)?'f ':V.has(n)?'v ':''}${AP.has(ds)?'c ':''}${ds===today()?'t ':''}${S.logs[ds]?'l':''}">${d}</button>`}
return `<h1 class="mo-h">Calendário</h1><div class="hm-card cl-c"><div class="cl-h"><button class="ob-back" data-a="cm" data-n="-1" aria-label="Mês anterior">${CHL}</button><h3>${MES[m]} ${y}</h3><button class="ob-back" data-a="cm" data-n="1" aria-label="Mês seguinte">${CHR}</button></div><div class="cal">${cells}</div>
<div class="lg">${(pg?LGI('background:var(--wn)','Consulta pré-natal'):(has.p?LGI('background:var(--ac)','Menstruação'):'')+(has.f?LGI('background:none;border:1.5px dashed var(--ac)','Previsão'):'')+(has.v?LGI('background:rgba(138,106,214,.3)','Fértil (estimativa)'):''))+(has.t?LGI('outline:2px solid var(--wn)','Hoje'):'')+(has.l?LGI('background:var(--wn);border-radius:50%','Sintomas registados'):'')}</div></div>
${pg?`<button class="btn hm-cta" data-a="appt" data-d="${today()}">${ic('cal')}<span>Marcar consulta pré-natal</span></button>${apptList()}`:'<button class="btn hm-cta" data-a="startP">'+ic('drop')+'<span>Minha menstruação começou</span></button>'}`}
function diary(){const ks=Object.keys(S.logs).sort().reverse();return `<h1 class="mo-h">Diário</h1><button class="btn hm-cta" data-a="day" data-d="${today()}">${ic('pencil')}<span>Registar hoje</span></button>`+(ks.length?ks.map(k=>{const l=S.logs[k],t=[...(l.q||[]).map(x=>Q.find(q=>q[0]===x)[2]),l.mood,l.flow&&'Fluxo '+l.flow.toLowerCase(),...(l.symptoms||[])].filter(Boolean);return `<button class="dy" data-a="day" data-d="${k}"><div class="dy-h"><b>${formatDate(k)}</b>${l.pain?`<span class="hm-pill hm-cm">Dor ${l.pain}/10</span>`:''}</div><div class="dy-c">${t.length?t.map(x=>`<span>${esc(x)}</span>`).join(''):'<span class="e">Sem sintomas</span>'}</div>${l.notes?`<div class="dy-n">“${esc(l.notes)}”</div>`:''}</button>`}).join(''):emp('pencil','Ainda sem registos','Regista como te sentes para começares o teu diário.'))}
function stats(){const L=cycleLens(),pd=S.cycles.map(calculatePeriodDuration).filter(Boolean),av=a=>a.length?(a.reduce((x,y)=>x+y)/a.length).toFixed(1).replace('.0',''):'—';
if(!S.cycles.length)return '<h1 class="mo-h">Estatísticas</h1>'+emptyC();
const mx=Math.max(...L,1),bars=L.slice(-8).map((v,i)=>`<div class="mu">${plural(v,'dia','dias')}</div><div class="bar" style="width:${Math.round(v/mx*100)}%"></div>`).join('');
const box=(l,v,i,k)=>`<div class="hm-s"><span class="si ${k}">${ic(i)}</span><div><b>${v}</b><small>${l}</small></div></div>`,d=n=>n+' dias';
return `<h1 class="mo-h">Estatísticas</h1><div class="hm-stats">${box('Média do ciclo',L.length?d(av(L)):'—','cyc','t2')}${box('Média da menstruação',pd.length?d(av(pd)):'—','drop','t1')}${box('Ciclo mais curto',L.length?d(Math.min(...L)):'—','chart','t4')}${box('Ciclo mais longo',L.length?d(Math.max(...L)):'—','chart','t3')}${box('Último ciclo',L.length?d(L[L.length-1]):'—','cal','t2')}${box('Ciclos registados',S.cycles.length,'doc','t1')}</div><h2 class="hm-t">Duração dos ciclos</h2><div class="hm-card">${L.length?bars:'<p class="mu" style="margin:0">Regista pelo menos duas menstruações para ver os gráficos.</p>'}</div>`}
const emptyC=()=>emp('cyc','Os teus ciclos aparecerão aqui','Quando a tua próxima menstruação começar, regista aqui.');
const ICN={'🌸':'heart','🩺':'cal','🗓️':'calh','🩸':'drop','💭':'pencil'};
const PGH=(t,to)=>ph(t,to);
const emp=(i,t,x)=>`<div class="em"><span class="si t1">${ic(i)}</span><b>${t}</b>${x?`<p>${x}</p>`:''}</div>`;
const CHL='<svg viewBox="0 0 24 24"><path d="M15 5l-7 7 7 7"/></svg>',CHR='<svg viewBox="0 0 24 24"><path d="M9 5l7 7-7 7"/></svg>';
function updBag(){const b=(S.cfg.preg||{}).bag||{},n=BAG.filter((x,i)=>b[i]).length,p=Math.round(n/BAG.length*100);const a=$('#bgc'),c=$('#bgx'),d=$('#bgp');if(a)a.textContent=n+' de '+BAG.length+' itens prontos';if(c)c.textContent=p+'%';if(d)d.style.width=p+'%'}
