function more(){const p=S.profile,f=p.name.trim().split(/\s+/)[0],n=unread();
return `<h1 class="mo-h">Mais</h1><button type="button" class="mo-pf" data-a="go" data-v="prof"><span class="av">${esc(f.charAt(0).toUpperCase())}</span><span class="st"><b>${esc(p.name)}</b><small>Ver e editar perfil</small></span><svg class="chv" viewBox="0 0 24 24"><path d="M9 5l7 7-7 7"/></svg></button>`
+sec('Acompanhar',rM('go','data-v="hist"','cyc','Histórico','t1')+rM('go','data-v="phases"','moon','Fases do ciclo','t2')+rM('pdf','','doc','Relatório em PDF','t3'))
+sec('Saber mais',rM('go','data-v="learn"','book','Aprende','t4')+rM('go','data-v="help"','help','Quando procurar ajuda','t1'))
+sec('Aplicação',rM('go','data-v="notif"','bell','Notificações','t2',n?(n>99?'99+':n):'')+rM('go','data-v="sett"','cog','Definições','t3'))
+sec('Sobre',`<div class="sb-h"><img class="sb-lg" src="icon.svg" width="44" height="44" alt=""><div><b>My Cycle+</b><small>Versão ${APP_VER}</small></div></div><p class="sb-p">O My Cycle+ é uma app pensada para te ajudar a acompanhar o ciclo menstrual e a gravidez, num só lugar. Regista a menstruação, os sintomas e o humor, e recebe previsões que ficam mais certas a cada ciclo.</p><p class="sb-t">Cuida de ti, ciclo após ciclo.</p>`,1)}
function hist(){const n=S.cycles.length;return PGH('Histórico','more')+(n?S.cycles.map((c,i)=>{const L=calculateCycleLength(i),d=calculatePeriodDuration(c);return `<button class="wd hs" data-a="editC" data-id="${c.id}"><span class="si t1 hs-n">${i+1}</span><div class="wd-t r"><b>${dm(c.start)} → ${c.end?dm(c.end):'em curso'}</b><small>${d?plural(d,'dia','dias'):'Duração por registar'}, ciclo ${L?plural(L,'dia','dias'):'em curso'}</small></div><svg class="chv" viewBox="0 0 24 24"><path d="M9 5l7 7-7 7"/></svg></button>`}).reverse().join(''):emptyC())+'<button class="btn" data-a="startP">+ Registar menstruação</button>'}
function phases(){const cp=calculateCyclePhase(),pl=cp.pl,ov=cp.ov,cl=cp.cl,L=[['Menstruação','1–'+pl,'O revestimento do útero é eliminado.','t1','drop'],['Fase folicular',(pl+1)+'–'+(ov-2),'O corpo prepara um novo óvulo.','t4','cyc'],['Ovulação (estimativa)',(ov-1)+'–'+(ov+1),'Pode variar muito de ciclo para ciclo.','t2','calh'],['Fase lútea',(ov+2)+'–'+cl,'O corpo prepara-se para o próximo ciclo.','t3','moon']];return PGH('Fases do ciclo','more')+L.map(x=>`<div class="wd ph-i${cp.n===x[0]?' now':''}"><span class="si ${x[3]}">${ic(x[4])}</span><div class="wd-t r"><b>${x[0]}</b><small>Dias ${x[1]} do ciclo</small><p>${x[2]}</p></div>${cp.n===x[0]?'<span class="hm-pill hm-cm">Agora</span>':''}</div>`).join('')}
function learn(){const T=[['O que é o ciclo menstrual?','É a sequência de mudanças que o corpo faz todos os meses. Conta-se do primeiro dia de uma menstruação até ao dia anterior à seguinte.'],['Por que a menstruação acontece?','Quando não há gravidez, o revestimento do útero é eliminado, o que causa o sangramento.'],['O que pode causar cólicas?','Contrações do útero durante a menstruação. Calor local, descanso e movimento suave costumam aliviar. Se a dor for forte, fala com um profissional de saúde.'],['Como cuidar de ti durante a menstruação?','Descansa quando precisas, bebe água, alimenta-te bem e escolhe o que te faz sentir confortável.'],['Quando procurar ajuda médica?','Consulta a área “Quando procurar ajuda” para ver os sinais de alerta.'],['Por que o ciclo pode variar?','Stress, sono, alimentação, mudanças de rotina e fases da vida podem alterar a duração do ciclo.'],['Menstruação irregular','Ciclos com durações muito diferentes entre si são considerados irregulares. Regista os teus ciclos e fala com um profissional se houver dúvidas.']];return PGH('Aprende','more')+'<div class="sg pad ap">'+T.map(t=>`<details><summary>${t[0]}</summary><p>${t[1]}</p></details>`).join('')+'</div>'}
function help(){const I=['sangramento muito intenso','dor muito forte ou incapacitante','desmaio','sintomas que te preocupam','alterações menstruais persistentes','ausência prolongada da menstruação, quando houver possibilidade de gravidez'];return PGH('Quando procurar ajuda','more')+'<p class="hp-l">Procura um profissional de saúde se tiveres:</p><div class="sg">'+I.map(t=>`<div class="sr" style="cursor:default"><span class="si t1">${ic('help')}</span><span class="st hp-t">${t.charAt(0).toUpperCase()+t.slice(1)}</span></div>`).join('')+'</div>'}
const ph=(t,to)=>`<div class="ph"><button class="ob-back" data-a="go" data-v="${to}" aria-label="Voltar"><svg viewBox="0 0 24 24"><path d="M15 5l-7 7 7 7"/></svg></button><h1>${t}</h1></div>`;
const sec=(t,b,pad)=>`<h2 class="sgt">${t}</h2><div class="sg${pad?' pad':''}">${b}</div>`;
const sIc=n=>`<span class="si">${ic(n)}</span>`;
const sTx=(t,d)=>`<span class="st"><b>${t}</b>${d?`<small>${d}</small>`:''}</span>`;
const rSw=(k,i,t,d,v)=>`<label class="sr">${sIc(i)}${sTx(t,d)}<input type="checkbox" class="tgi" data-c="${k}" ${v?'checked':''}><i class="tgs"></i></label>`;
const rSel=(k,i,t,d,o,cur)=>`<label class="sr">${sIc(i)}${sTx(t,d)}<select class="ssel" data-c="${k}">${o.map(x=>`<option value="${x[0]}" ${String(x[0])===String(cur)?'selected':''}>${x[1]}</option>`).join('')}</select></label>`;
const rGo=(a,i,t,d,val,cls,ex)=>`<button type="button" class="sr sb ${cls||''}" data-a="${a}" ${ex||''}>${sIc(i)}${sTx(t,d)}${val?`<span class="sv">${val}</span>`:''}<svg class="chv" viewBox="0 0 24 24"><path d="M9 5l7 7-7 7"/></svg></button>`;
function sett(){const p=S.profile,c=S.cfg,r=c.rem||{},t=localStorage.getItem('ff-theme')||'auto',lc=lastC(),w=c.w||{},pg=c.preg&&c.preg.on;
return ph('Definições','more')
+sec('O teu ciclo',`${fld('sl','Última menstruação','cal','type="date" max="'+today()+'"',lc?lc.start:'')}${stp('sp','Menstruação','Dias de fluxo',p.periodLen,1,15)}${stp('scl','Ciclo','Dias entre menstruações',p.cycleLen,15,60)}<div id="e2" class="ob-err" role="alert"></div><button class="btn" data-a="saveC">Guardar ciclo</button>`,1)
+sec('Calendário',rSw('calFert','calh','Mostrar janela fértil','Dias férteis estimados no calendário',c.calFert))
+sec('Notificações',rSw('rem.before','bell','Antes da menstruação','Avisa-te quando estiver a chegar',r.before!==false)+rSw('rem.start','cal','Registar o início','Lembra-te de registar quando começar',r.start!==false)+rSw('rem.sym','pencil','Registar sintomas','Um lembrete para registares como te sentes',r.sym!==false)+rSel('rem.days','clock','Avisar com antecedência','',[[1,'1 dia'],[2,'2 dias'],[3,'3 dias'],[5,'5 dias']],r.days||2))

+sec('Privacidade e segurança',rGo('pin','lock','Bloqueio da app','',c.pin?LT[c.ltype||'pin']:'Desativado')+(c.pin?rGo('bioreg','finger','Biometria','',c.bio?'Ativa':'Desativada'):'')+rSel('alock','clock','Bloqueio automático',c.pin?'Bloqueia após inatividade':'Precisa do bloqueio ativo',[[0,'Nunca'],[1,'1 minuto'],[2,'2 minutos'],[5,'5 minutos'],[10,'10 minutos']],c.alock||0)+rSw('discreet','eyeoff','Modo discreto','Desfoca as datas no início e torna os avisos genéricos',c.discreet)+rSw('hideName','shield','Esconder o nome da app','Nas notificações aparece só “Lembrete”',c.hideName))
+sec('Aparência',rSel('theme','moon','Tema','Segue o sistema ou escolhe',[['auto','Automático'],['light','Claro'],['dark','Escuro']],t))
+sec('Ecrã inicial',rSw('w.fert','calh','Janela fértil','Estimativa dos dias férteis',w.fert!==false)+rSw('w.water','drop','Copos de água','Contador diário',w.water!==false)+rSw('w.tip','info','Dica do dia','',w.tip!==false))
+sec('Gravidez',rGo(pg?'pregOff':'preg','heart',pg?'Terminar modo gravidez':'Ativar modo gravidez','Pausa as previsões do ciclo e mostra o acompanhamento da gravidez'))
+sec('Dados e backup',rGo('pdf','doc','Relatório em PDF','Para levar à consulta')+rGo('export','download','Exportar os meus dados','Cópia de segurança em ficheiro')+rGo('import','upload','Importar ficheiro','Restaura uma cópia de segurança')+rGo('impTxt','clip','Importar colando texto','')+'<input type="file" id="fi" accept="application/json,.json" hidden>')

+sec('Apagar',rGo('wipe','trash','Apagar todos os dados','Remove o perfil, os ciclos e o diário deste telemóvel','','dng'))}
/* ===== painéis ===== */
function startP(){sheet(`<h2 style="margin-top:0">Quando começou?</h2>${fld('ps','Início','cal','type="date" max="'+today()+'"',today())}${fld('pe','Fim (opcional)','cal','type="date" max="'+today()+'"','')}<div id="pr" class="ob-err" role="alert"></div><button class="btn" data-a="saveStart">Guardar</button><button class="btn s" data-a="close">Cancelar</button>`)}
function validateCycle(s,e,id){if(!validDate(s))return'Por favor, indica a data em que começou a tua menstruação.';if(d2n(s)>d2n(today()))return'A data de início não pode estar no futuro.';if(e){if(!validDate(e))return'A data de fim não é válida.';if(d2n(e)<d2n(s))return'A data de fim não pode ser anterior ao início.';if(d2n(e)-d2n(s)>14)return'A menstruação não pode durar mais de 15 dias.'}
if(S.cycles.some(c=>c.id!==id&&Math.abs(d2n(c.start)-d2n(s))<10))return'Já existe um registo muito próximo desta data.';
if(e&&S.cycles.some(c=>c.id!==id&&d2n(c.start)>d2n(s)&&d2n(c.start)<=d2n(e)))return'O fim não pode ultrapassar o início do ciclo seguinte.';return''}
async function saveCycle(s,e,id){const er=validateCycle(s,e,id);if(er)return er;const o={start:s,end:e||null,createdAt:Date.now()};if(id){const old=S.cycles.find(c=>c.id===id);o.id=id;o.createdAt=old.createdAt;o.notes=old.notes}await dbPut('cycles',o);await load();return''}
function dayS(d){const l=S.logs[d]||{};sheet(`<h2 style="margin-top:0">${formatDate(d)}</h2>${S.cfg.preg&&S.cfg.preg.on?`<button class="btn s" data-a="appt" data-d="${d}">${ic('cal')}Marcar consulta pré-natal</button>`:`<div class="row"><button class="btn s" data-a="pStart" data-d="${d}">${ic('drop')}Começou</button><button class="btn s" data-a="pEnd" data-d="${d}">Terminou</button></div>`}<label>Humor</label>${chips('mood',MOOD,l.mood,1)}<label>Sintomas</label>${chips('sym',SYM,l.symptoms)}<label>Fluxo</label>${chips('flow',FLOW,l.flow,1)}<label>Dor: <span id="pv">${l.pain||0}</span>/10</label><input id="pain" type="range" min="0" max="10" value="${l.pain||0}" oninput="pv.textContent=this.value"><label>Observações</label><textarea id="nt" maxlength="500">${esc(l.notes||'')}</textarea><input type="hidden" id="dd" value="${d}"><button class="btn" data-a="saveDay">Guardar</button>${S.logs[d]?'<button class="btn s" data-a="delDay" data-d="'+d+'">Apagar registo do dia</button>':''}`)}
function editC(id){const c=S.cycles.find(x=>x.id===id);sheet(`<h2 style="margin-top:0">Editar menstruação</h2>${fld('ps','Início','cal','type="date" max="'+today()+'"',c.start)}${fld('pe','Fim','cal','type="date" max="'+today()+'"',c.end||'')}<div id="pr" class="ob-err" role="alert"></div><button class="btn" data-a="saveEdit" data-id="${id}">Guardar</button><button class="btn d" data-a="delC" data-id="${id}">Apagar</button>`)}
const msgOK=m=>{closeSheet();render();toast(m)};
/* ===== ações ===== */
const A={
go:e=>{V=e.dataset.v;render()},close:closeSheet,reveal:e=>{if(!S.cfg.discreet)return;REV=!REV;clearTimeout(revT);if(REV)revT=setTimeout(()=>{REV=false;if(V==='home')render()},4000);render()},
cm:e=>{cm.m+=+e.dataset.n;if(cm.m<0){cm.m=11;cm.y--}if(cm.m>11){cm.m=0;cm.y++}render()},
chip:e=>{if(e.dataset.s==='1'){const was=e.classList.contains('on');$$('[data-g="'+e.dataset.g+'"]').forEach(x=>x.classList.remove('on'));if(!was)e.classList.add('on')}else e.classList.toggle('on')},
startP,day:e=>dayS(e.dataset.d),editC:e=>editC(+e.dataset.id),
async quick(e){const d=today(),l=S.logs[d]||{date:d};l.q=l.q||[];const k=e.dataset.k;l.q=l.q.includes(k)?l.q.filter(x=>x!==k):[...l.q,k];await dbPut('logs',l);await load();render()},
async saveStart(){const s=$('#ps').value,e=$('#pe').value,er=await saveCycle(s,e);if(er)return $('#pr').textContent=er;msgOK('Menstruação registada ♥')},
async saveEdit(el){const er=await saveCycle($('#ps').value,$('#pe').value,+el.dataset.id);if(er)return $('#pr').textContent=er;msgOK('Alterações guardadas ♥')},
async delC(el){if(S.cycles.length<2)return $('#pr').textContent='Tens de manter pelo menos um ciclo registado.';await dbDel('cycles',+el.dataset.id);await load();msgOK('Registo apagado')},
async pStart(el){const er=await saveCycle(el.dataset.d,null);if(er)return toast(er);msgOK('Menstruação registada ♥')},
async pEnd(el){const d=el.dataset.d,c=[...S.cycles].reverse().find(x=>d2n(x.start)<=d2n(d));if(!c)return toast('Regista primeiro o início da menstruação.');const er=await saveCycle(c.start,d,c.id);if(er)return toast(er);msgOK('Fim registado ♥')},
async saveDay(){const d=$('#dd').value,g=k=>$$('[data-g="'+k+'"].on').map(x=>x.textContent),o=S.logs[d]||{date:d};Object.assign(o,{date:d,mood:g('mood')[0]||'',symptoms:g('sym'),flow:g('flow')[0]||'',pain:+$('#pain').value,notes:$('#nt').value.trim().slice(0,500)});await dbPut('logs',o);await load();msgOK('Registo guardado ♥')},
async delDay(el){await dbDel('logs',el.dataset.d);await load();msgOK('Registo apagado')},
async saveP(){const n=$('#sn').value.trim(),a=+$('#sa').value,c=$('#sc').value.trim();if(!n)return fe('sn','Por favor, indica o teu nome.','e1');if(!$('#sa').value||!Number.isInteger(a)||a<8||a>99)return fe('sa','Indica uma idade válida (entre 8 e 99).','e1');if(!c)return fe('sc','Por favor, indica a tua cidade.','e1');Object.assign(S.profile,{name:n.slice(0,40),age:a,city:c.slice(0,60)});await dbPut('profile',S.profile);toast('Perfil guardado ♥');render()},
async saveC(){const pl=+$('#sp').value,cl=+$('#scl').value,l=$('#sl').value;if(!Number.isInteger(pl)||pl<1||pl>15||!Number.isInteger(cl)||cl<15||cl>60)return fe('sp','Menstruação: 1–15 dias. Ciclo: 15–60 dias.','e2');if(!validDate(l))return fe('sl','Por favor, indica a data em que começou a tua última menstruação.','e2');
const c=lastC();if(c.start!==l){const er=await saveCycle(l,c.end&&d2n(c.end)>=d2n(l)?c.end:null,c.id);if(er)return fe('sl',er,'e2')}
Object.assign(S.profile,{periodLen:pl,cycleLen:cl,unknown:false});await dbPut('profile',S.profile);await load();toast('Ciclo atualizado ♥');render()},
pin(){const h=!!S.cfg.pin;sheet(`<h2 style="margin-top:0">${h?'Alterar ou desativar PIN':'Criar PIN'}</h2>${fld('p1','Novo PIN (4 a 8 números)','lock','type="password" inputmode="numeric" maxlength="8"','')}${fld('p2','Confirmar PIN','lock','type="password" inputmode="numeric" maxlength="8"','')}<div id="pr" class="ob-err" role="alert"></div><button class="btn" data-a="savePin">Guardar PIN</button>${h?'<button class="btn d" data-a="offPin">Desativar PIN</button>':''}`)},
async savePin(){const a=$('#p1').value,b=$('#p2').value;if(!/^\d{4,8}$/.test(a))return $('#pr').textContent='O PIN deve ter 4 a 8 números.';if(a!==b)return $('#pr').textContent='Os PINs não coincidem.';S.cfg.pin=await hash(a);await saveCfg();msgOK('PIN ativado ♥');render()},
async offPin(){delete S.cfg.pin;delete S.cfg.bio;delete S.cfg.ltype;delete S.cfg.plen;await saveCfg();msgOK('PIN desativado');render()},
async bioreg(){if(!window.PublicKeyCredential)return toast('Biometria não suportada neste navegador.');toast(await bioReg()?'Biometria ativada ♥':'Não foi possível ativar a biometria.');render()},
async unlock(){if(await hash($('#lpin').value)===S.cfg.pin){$('#lpin').value='';openApp()}else $('#lerr').textContent='PIN incorreto.'},
async bioauth(){if(await bioAuth()){openApp()}else $('#lerr').textContent='Biometria não confirmada.'},
export(){const o={app:'fanny-app',version:1,exported:new Date().toISOString(),profile:S.profile,cycles:S.cycles,logs:Object.values(S.logs),cfg:{...S.cfg,pin:undefined,bio:undefined,salt:undefined}};saveFile(new Blob([JSON.stringify(o,null,1)],{type:'application/json'}),'my-cycle-backup-'+today()+'.json')},
import(){$('#fi').click()},
wipe(){sheet('<h2 style="margin-top:0">Tem certeza?</h2><p>Esta ação não pode ser desfeita.</p><button class="btn d" data-a="wipeOK">Sim, apagar tudo</button><button class="btn s" data-a="close">Cancelar</button>')},
async wipeOK(){for(const s of['profile','cycles','logs','settings'])await dbClr(s);localStorage.clear();location.reload()},
async finish(){enter()}
};
document.addEventListener('click',e=>{const t=e.target.closest('[data-a]');if(t&&A[t.dataset.a])A[t.dataset.a](t)});
document.addEventListener('input',e=>{const w=e.target.closest&&e.target.closest('.fld');if(w){w.classList.remove('bad');$$('.ob-err').forEach(x=>x.textContent='')}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='fi'){importFile(t.files[0]);t.value='';return}const k=t.dataset.c;if(!k)return;
if(k==='theme'){localStorage.setItem('ff-theme',t.value);theme();return}
const v=t.type==='checkbox'?t.checked:+t.value;if(k.startsWith('bag.')){S.cfg.preg.bag=S.cfg.preg.bag||{};S.cfg.preg.bag[k.slice(4)]=v;updBag()}else if(k.startsWith('w.')){S.cfg.w=S.cfg.w||{};S.cfg.w[k.slice(2)]=v}else if(k.startsWith('rem.')){S.cfg.rem=S.cfg.rem||{};S.cfg.rem[k.slice(4)]=v;if(v===true&&'Notification' in window&&Notification.permission==='default')Notification.requestPermission()}else S.cfg[k]=v;await saveCfg();toast('Guardado ♥')});
async function importFile(f){if(f)importText(await f.text())}
async function importText(txt){try{const o=JSON.parse(txt);if(o.app!=='fanny-app'||!o.profile||!Array.isArray(o.cycles)||!Array.isArray(o.logs))throw 0;const p=o.profile;if(!p.name||!(p.cycleLen>=15&&p.cycleLen<=60)||!(p.periodLen>=1&&p.periodLen<=15)||!o.cycles.length)throw 0;if(o.cycles.some(c=>!validDate(c.start)||(c.end&&!validDate(c.end)))||o.logs.some(l=>!validDate(l.date)))throw 0;
const keep={pin:S.cfg.pin,bio:S.cfg.bio,salt:S.cfg.salt};for(const s of['profile','cycles','logs'])await dbClr(s);p.id=1;await dbPut('profile',p);for(const c of o.cycles)await dbPut('cycles',{...c,id:undefined,...(c.id?{id:c.id}:{})}).catch(()=>0);for(const l of o.logs)await dbPut('logs',l);S.cfg={...(o.cfg||{}),...keep};await saveCfg();await load();render();closeSheet();toast('Dados importados ♥')}catch(e){toast('Ficheiro inválido. Nada foi alterado.')}}
