const LT={pin:'PIN',pass:'Palavra-passe',pat:'Padrão'};let PS=null;
function patPad(el,cb){el.innerHTML='<div class="pp"><svg viewBox="0 0 300 300"><polyline fill="none" stroke="#b4566f" stroke-width="6" stroke-linecap="round" stroke-linejoin="round" points=""/></svg>'+[...Array(9)].map((_,i)=>`<i style="left:${(i%3)*33.333+16.667}%;top:${Math.floor(i/3)*33.333+16.667}%"></i>`).join('')+'</div>';
const pp=el.firstChild,pl=pp.querySelector('polyline'),ds=[...pp.querySelectorAll('i')];let seq=[],on=false,pt=[];
const hit=e=>{const r=pp.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*300,y=(e.clientY-r.top)/r.height*300,c=Math.floor(x/100),w=Math.floor(y/100);return{x,y,i:(c<0||c>2||w<0||w>2)?-1:Math.hypot(x-(c*100+50),y-(w*100+50))<38?w*3+c:-1}};
const mv=e=>{if(!on)return;const h=hit(e);if(h.i>=0&&!seq.includes(h.i)){seq.push(h.i);ds[h.i].classList.add('on');pt.push((h.i%3*100+50)+','+(Math.floor(h.i/3)*100+50))}pl.setAttribute('points',pt.concat(h.x+','+h.y).join(' '))};
pp.addEventListener('pointerdown',e=>{on=true;seq=[];pt=[];ds.forEach(d=>d.classList.remove('on'));try{pp.setPointerCapture(e.pointerId)}catch(x){}mv(e)});
pp.addEventListener('pointermove',mv);
const end=()=>{if(!on)return;on=false;pl.setAttribute('points',pt.join(' '));const s=seq.slice();setTimeout(()=>{ds.forEach(d=>d.classList.remove('on'));pl.setAttribute('points','')},350);if(s.length)cb(s)};
pp.addEventListener('pointerup',end);pp.addEventListener('pointercancel',end)}
function drawDots(){const i=$('#lpin'),d=$('#ldots');if(!d||!i)return;const L=S.cfg.plen,v=i.value.length,n=L||Math.max(4,v);d.innerHTML=Array.from({length:n},(_,k)=>'<i'+(k<v?' class="on'+(k===v-1?' p':'')+'"':'')+'></i>').join('')}
